#include <stdlib.h>
#include <string.h>
#include <stdint.h>

/* Blockchain smart contract runtime - multi-tenant execution engine */
/* Each tenant has isolated state, callbacks execute asynchronously */

#define MAX_TENANTS 64
#define MAX_CALLBACKS 128
#define SLOT_ACTIVE 1
#define SLOT_PENDING 2
#define SLOT_FREED 0

typedef struct tenant_state {
    uint64_t tenant_id;
    uint8_t *storage_root;
    uint32_t storage_size;
    uint32_t ref_count;
    uint8_t isolation_level;
    uint64_t generation;  /* monotonic generation counter */
} tenant_state_t;

typedef struct callback_entry {
    uint64_t cb_id;
    uint64_t tenant_id;
    void (*handler)(void *ctx, uint8_t *result, uint32_t len);
    void *ctx;  /* points to tenant-specific context */
    uint8_t status;
    uint32_t epoch;
} callback_entry_t;

typedef struct contract_runtime {
    tenant_state_t tenants[MAX_TENANTS];
    callback_entry_t callbacks[MAX_CALLBACKS];
    uint32_t current_epoch;
    uint32_t active_tenants;
    uint64_t next_cb_id;
    uint64_t generation_counter;
} contract_runtime_t;

static contract_runtime_t g_runtime;

typedef struct async_context {
    tenant_state_t *tenant_ref;
    uint8_t *scratch_buffer;
    uint32_t scratch_size;
    uint64_t nonce;
    uint64_t tenant_generation;  /* captured at schedule time */
    uint64_t expected_tenant_id; /* captured tenant identity */
} async_context_t;

/* Initialize runtime */
void runtime_init(void) {
    memset(&g_runtime, 0, sizeof(contract_runtime_t));
    g_runtime.current_epoch = 1;
    g_runtime.next_cb_id = 1000;
    g_runtime.generation_counter = 1;
}

/* Register a new tenant */
int register_tenant(uint64_t tenant_id, uint32_t storage_size) {
    if (storage_size == 0 || storage_size > 1048576) return -1;
    for (int i = 0; i < MAX_TENANTS; i++) {
        if (g_runtime.tenants[i].tenant_id == 0) {
            g_runtime.tenants[i].tenant_id = tenant_id;
            g_runtime.tenants[i].storage_root = (uint8_t *)calloc(1, storage_size);
            if (!g_runtime.tenants[i].storage_root) return -1;
            g_runtime.tenants[i].storage_size = storage_size;
            g_runtime.tenants[i].ref_count = 1;
            g_runtime.tenants[i].isolation_level = 3;
            g_runtime.tenants[i].generation = g_runtime.generation_counter++;
            g_runtime.active_tenants++;
            return i;
        }
    }
    return -1;
}

/* Callback handler for cross-tenant oracle queries */
static void oracle_result_handler(void *ctx, uint8_t *result, uint32_t len) {
    async_context_t *async_ctx = (async_context_t *)ctx;
    /* Validate tenant reference is still valid via generation check */
    tenant_state_t *tenant = async_ctx->tenant_ref;

    /* Generation guard: ensure the tenant slot still holds the SAME tenant */
    if (tenant->generation != async_ctx->tenant_generation ||
        tenant->tenant_id != async_ctx->expected_tenant_id ||
        tenant->tenant_id == 0) {
        /* Stale reference - tenant was evicted and possibly replaced */
        if (async_ctx->scratch_buffer) {
            free(async_ctx->scratch_buffer);
        }
        free(async_ctx);
        return;
    }

    if (len > 0 && len <= tenant->storage_size && tenant->storage_root != NULL) {
        /* Write oracle result into tenant's storage */
        memcpy(tenant->storage_root, result, len);
    }

    if (async_ctx->scratch_buffer) {
        free(async_ctx->scratch_buffer);
    }
    free(async_ctx);
}

/* Schedule an async oracle query for a tenant */
uint64_t schedule_oracle_query(int tenant_idx, uint8_t *query, uint32_t query_len) {
    if (tenant_idx < 0 || tenant_idx >= MAX_TENANTS) return 0;
    if (g_runtime.tenants[tenant_idx].tenant_id == 0) return 0;
    if (query_len == 0 || query_len > 4096) return 0;

    async_context_t *ctx = (async_context_t *)malloc(sizeof(async_context_t));
    if (!ctx) return 0;

    ctx->tenant_ref = &g_runtime.tenants[tenant_idx];
    ctx->tenant_generation = g_runtime.tenants[tenant_idx].generation;
    ctx->expected_tenant_id = g_runtime.tenants[tenant_idx].tenant_id;
    ctx->scratch_buffer = (uint8_t *)malloc(query_len);
    ctx->scratch_size = query_len;
    ctx->nonce = g_runtime.next_cb_id;

    if (ctx->scratch_buffer) {
        memcpy(ctx->scratch_buffer, query, query_len);
    } else {
        free(ctx);
        return 0;
    }

    /* Find free callback slot */
    for (int i = 0; i < MAX_CALLBACKS; i++) {
        if (g_runtime.callbacks[i].status == SLOT_FREED) {
            g_runtime.callbacks[i].cb_id = g_runtime.next_cb_id++;
            g_runtime.callbacks[i].tenant_id = g_runtime.tenants[tenant_idx].tenant_id;
            g_runtime.callbacks[i].handler = oracle_result_handler;
            g_runtime.callbacks[i].ctx = ctx;
            g_runtime.callbacks[i].status = SLOT_PENDING;
            g_runtime.callbacks[i].epoch = g_runtime.current_epoch;
            return g_runtime.callbacks[i].cb_id;
        }
    }

    free(ctx->scratch_buffer);
    free(ctx);
    return 0;
}

/* Evict a tenant - called during garbage collection or admin action */
int evict_tenant(int tenant_idx) {
    if (tenant_idx < 0 || tenant_idx >= MAX_TENANTS) return -1;
    if (g_runtime.tenants[tenant_idx].tenant_id == 0) return -1;

    /* Free tenant storage */
    if (g_runtime.tenants[tenant_idx].storage_root) {
        free(g_runtime.tenants[tenant_idx].storage_root);
        g_runtime.tenants[tenant_idx].storage_root = NULL;
    }

    /* Mark tenant slot as available - generation stays to invalidate stale refs */
    g_runtime.tenants[tenant_idx].storage_size = 0;
    g_runtime.tenants[tenant_idx].tenant_id = 0;
    g_runtime.tenants[tenant_idx].ref_count = 0;
    /* generation is NOT reset - it will get a new value on re-registration */
    g_runtime.active_tenants--;

    return 0;
}

/* Process pending callbacks - simulates async completion */
int process_callbacks(uint8_t *oracle_data, uint32_t data_len) {
    int processed = 0;
    if (data_len == 0 || oracle_data == NULL) return 0;

    for (int i = 0; i < MAX_CALLBACKS; i++) {
        if (g_runtime.callbacks[i].status == SLOT_PENDING) {
            /* Epoch check: only process callbacks from current or previous epoch.
             * Use addition to avoid unsigned underflow when current_epoch is small. */
            if ((uint64_t)g_runtime.callbacks[i].epoch + 1 >= (uint64_t)g_runtime.current_epoch) {
                g_runtime.callbacks[i].handler(
                    g_runtime.callbacks[i].ctx,
                    oracle_data,
                    data_len
                );
                g_runtime.callbacks[i].status = SLOT_FREED;
                g_runtime.callbacks[i].ctx = NULL;
                processed++;
            }
        }
    }

    return processed;
}

/* Advance epoch - triggers GC of old callbacks */
void advance_epoch(void) {
    g_runtime.current_epoch++;

    /* Purge callbacks older than 2 epochs */
    for (int i = 0; i < MAX_CALLBACKS; i++) {
        if (g_runtime.callbacks[i].status == SLOT_PENDING &&
            (uint64_t)g_runtime.callbacks[i].epoch + 2 < (uint64_t)g_runtime.current_epoch) {
            if (g_runtime.callbacks[i].ctx) {
                async_context_t *ctx = (async_context_t *)g_runtime.callbacks[i].ctx;
                if (ctx->scratch_buffer) free(ctx->scratch_buffer);
                free(ctx);
            }
            g_runtime.callbacks[i].status = SLOT_FREED;
            g_runtime.callbacks[i].ctx = NULL;
        }
    }
}

/* Entry point demonstrating safe behavior */
int main(void) {
    runtime_init();

    /* Tenant A registers and schedules oracle query */
    int idx_a = register_tenant(0xAAAA, 256);
    uint8_t query[] = "price_feed_ETH_USD";
    uint64_t cb_id = schedule_oracle_query(idx_a, query, sizeof(query));

    /* Tenant A is evicted (e.g., insufficient gas, admin action) */
    evict_tenant(idx_a);

    /* New tenant B takes the same slot */
    int idx_b = register_tenant(0xBBBB, 512);

    /* Oracle result arrives - callback fires but generation check prevents write */
    /* tenant_ref points to slot that now has different generation + tenant_id */
    uint8_t result[] = "BLOCKED_CROSS_TENANT_WRITE";
    process_callbacks(result, sizeof(result));

    return 0;
}
